mapper.select:


WHERE 1 = 1


  AND (
  LOCATE(TRIM(#{query.keyword}), u.nickname) > 0
  OR LOCATE(TRIM(#{query.keyword}), u.email) > 0
  )



  AND u.company_id = #{query.companyId}



  AND u.status = #{query.status}



  AND EXISTS (
  SELECT 1
  FROM user_roles ur

  INNER JOIN roles r
  ON r.id = ur.role_id

  WHERE ur.user_id = u.id
  AND r.code = #{query.roleCode}
  )


ORDER BY u.created_at DESC, u.id DESC
